```ts
private async ensureReady(): Promise<void> {
  await this.initialize();
  // `isready`/`readyok` is the UCI barrier that guarantees prior commands
  // (setoption, position) have been fully applied.
  await new Promise<void>((resolve, reject) => {
    const waiter = {
      resolve,
      reject,
      timer: setTimeout(() => {
        this.readyWaiters = this.readyWaiters.filter((w) => w !== waiter);
        // The engine is wedged; force a fresh worker on the next call.
        this.isInitialized = false;
        this.initializationPromise = null;
        reject(new Error('Stockfish did not acknowledge isready in time'));
      }, READY_TIMEOUT_MS),
    };
    this.readyWaiters.push(waiter);
    try {
      this.post('isready');
    } catch (error) {
      clearTimeout(waiter.timer);
      this.readyWaiters = this.readyWaiters.filter((w) => w !== waiter);
      reject(error instanceof Error ? error : new Error(String(error)));
    }
  });
}
```

