  leaveGame(socketId: string): { room: GameRoomInternal; color: PieceColor } | null {
    const gameId = this.playerToRoom.get(socketId);
    if (!gameId) return null;

    const room = this.rooms.get(gameId);
    if (!room) return null;

    // An explicit leave gives up the seat. Unlike 'disconnect', which keeps the
    // seat so the player can reconnect, holding it here would leave the room
    // full forever: joinGame() rejects on occupancy alone, so nobody -- not even
    // the leaver -- could ever enter this gameId again.
    let color: PieceColor = 'white';
    if (room.whitePlayer?.socketId === socketId) {
      room.whitePlayer = null;
      color = 'white';
    } else if (room.blackPlayer?.socketId === socketId) {
      room.blackPlayer = null;
      color = 'black';
    }

    this.playerToRoom.delete(socketId);
    room.updatedAt = Date.now();

    // Last player out: drop the room now rather than waiting for cleanup().
    if (!room.whitePlayer && !room.blackPlayer) {
      this.rooms.delete(gameId);
      this.gameIdToRoomId.delete(gameId);
    }

    return { room, color };
  }
